-- ============================================================
-- Maddaniello's Physique — Schema v13 (seed libreria esercizi)
-- Richiede 0012_workout_tracking.sql già applicata.
--
-- Popola `exercise_catalog` con la libreria GLOBALE (user_id null):
-- ~150 esercizi che coprono tutti i distretti muscolari, con nomi
-- italiani "da palestra" + alias (inclusi i termini inglesi) per il
-- picker e per il matching dell'AI.
--
-- I metadati biomeccanici (biomech_notes, cues, common_errors,
-- contraindications, discouraged) seguono l'impostazione di
-- "Project Exercise Vol.2" — Andrea Roncari / Project inVictus:
--   * il ROM completo non è di per sé pericoloso, il carico mal gestito sì
--   * i vincoli antropometrici (leve, mobilità) guidano la scelta della variante
--   * alcuni esercizi classici sono marcati discouraged perché il rapporto
--     costo/beneficio articolare è sfavorevole (sit-up con piedi bloccati,
--     side bending e torsioni sotto carico, adductor/abductor machine)
--
-- Idempotente: `on conflict do nothing` sull'unique index
-- exercise_catalog_global_name_unique (lower(name) where user_id is null).
-- ============================================================

insert into exercise_catalog (
  user_id, name, aliases, primary_muscle, secondary_muscles, equipment,
  movement_pattern, plane, joint_type, is_unilateral, tracking_type,
  biomech_notes, cues, common_errors, contraindications,
  tier, discouraged, discouraged_reason, default_rest_sec
) values

-- ============================================================
-- PETTO
-- ============================================================
(null, 'Panca piana con bilanciere',
 array['bench press','panca piana','distensioni su panca piana','flat bench press'],
 'petto', array['tricipiti','deltoide_anteriore'], 'bilanciere', 'push_h', 'transverse', 'multi', false, 'weight_reps',
 'Spinta orizzontale su spalla e gomito: il grande pettorale adduce e flette orizzontalmente l''omero mentre il tricipite estende il gomito. Il momento della gravità sulla spalla è massimo quando il bilanciere si allontana dalla verticale della articolazione, per questo la traiettoria leggermente obliqua verso l''alto riduce lo stress. Scapole retratte e depresse creano una base stabile e limitano il conflitto sub-acromiale.',
 array['Scapole retratte e depresse, petto in fuori per tutta la serie','Piedi ben piantati a terra, arco lombare fisiologico senza staccare i glutei','Bilanciere che tocca all''altezza dello sterno basso, gomiti a 45-60 gradi dal busto','Polsi neutri e allineati sopra i gomiti','Spingi mantenendo la tensione, senza rimbalzare sul petto'],
 '[{"error":"Gomiti aperti a 90 gradi rispetto al busto","cause":"Ricerca di un allungamento massimo del pettorale","fix":"Porta i gomiti a 45-60 gradi: riduci lo stress su capsula anteriore e cuffia mantenendo la tensione sul petto"},{"error":"Rimbalzo del bilanciere sullo sterno","cause":"Carico eccessivo e ricerca di ripetizioni facili","fix":"Cala il carico, tocca il petto in controllo e riparti senza slancio"},{"error":"Scapole libere che si protraggono in spinta","cause":"Mancato set-up scapolare","fix":"Imposta retrazione e depressione prima di staccare e mantienile fino a fine serie"}]'::jsonb,
 'Dolore acromion-claveare o instabilità anteriore di spalla: ridurre il ROM o passare ai manubri con presa neutra.',
 1, false, null, 180),

(null, 'Panca inclinata con bilanciere',
 array['incline bench press','panca inclinata','distensioni su panca inclinata'],
 'petto', array['deltoide_anteriore','tricipiti'], 'bilanciere', 'push_h', 'sagittal', 'multi', false, 'weight_reps',
 'Con inclinazione 30-45 gradi il vettore di spinta si avvicina alla flessione di spalla, aumentando il contributo del capo clavicolare del pettorale e del deltoide anteriore. Oltre i 45 gradi l''esercizio diventa progressivamente una spinta sopra la testa. Non esiste un petto "alto" separato: cambia la porzione di fibre più sollecitata, non un muscolo diverso.',
 array['Inclinazione della panca tra 30 e 45 gradi','Scapole retratte e depresse contro lo schienale','Bilanciere che tocca sotto le clavicole, non sulla gola','Gomiti leggermente più chiusi rispetto alla panca piana','Spinta verticale sopra la linea delle spalle'],
 '[{"error":"Inclinazione troppo alta (oltre 60 gradi)","cause":"Convinzione di isolare il petto alto","fix":"Resta tra 30 e 45 gradi: sopra i 60 il lavoro passa quasi tutto al deltoide anteriore"},{"error":"Bacino che scivola e schiena che si stacca","cause":"Carico eccessivo","fix":"Riduci il peso e mantieni appoggio continuo di glutei e dorso"}]'::jsonb,
 null,
 2, false, null, 150),

(null, 'Panca declinata con bilanciere',
 array['decline bench press','panca declinata'],
 'petto', array['tricipiti'], 'bilanciere', 'push_h', 'transverse', 'multi', false, 'weight_reps',
 'La declinazione porta il vettore di spinta verso il basso, enfatizzando le fibre costo-sternali del pettorale e riducendo il coinvolgimento del deltoide anteriore. Il ROM è più corto e permette carichi maggiori, con minore stress sul cingolo scapolare. Utile a chi ha spalle irritabili nella panca piana.',
 array['Blocca bene le gambe nei supporti prima di staccare','Bilanciere che tocca all''altezza dello sterno basso','Gomiti chiusi verso il busto','Evita apnee prolungate per la posizione a testa in giù'],
 '[{"error":"Testa che si stacca cercando di guardare il bilanciere","cause":"Ricerca del controllo visivo","fix":"Tieni la nuca appoggiata e usa uno spotter per la traiettoria"},{"error":"ROM ridotto al minimo per caricare di più","cause":"Ego lifting","fix":"Scendi fino al contatto controllato con lo sterno"}]'::jsonb,
 'Ipertensione, reflusso gastroesofageo o cefalee da posizione declinata: preferire la panca piana.',
 2, false, null, 150),

(null, 'Distensioni su panca piana con manubri',
 array['dumbbell bench press','panca piana con manubri','spinte con manubri'],
 'petto', array['tricipiti','deltoide_anteriore'], 'manubri', 'push_h', 'transverse', 'multi', false, 'weight_reps',
 'I manubri liberano la spalla dal vincolo del bilanciere: la traiettoria può adattarsi alla morfologia individuale e il ROM in allungamento è maggiore. Il momento resistente resta massimo in posizione bassa, dove il pettorale è più allungato. Richiede più stabilizzazione della cuffia dei rotatori e quindi carichi inferiori.',
 array['Porta i manubri in posizione con le ginocchia, sdraiandoti indietro in blocco','Scapole retratte e depresse','Scendi finché i gomiti arrivano poco sotto la linea del busto','Non far scontrare i manubri in alto: fermati prima, mantenendo tensione','Polsi neutri, manubri sopra i gomiti'],
 '[{"error":"Discesa oltre il limite di mobilità della spalla","cause":"Ricerca di stretch estremo","fix":"Scendi fino a dove controlli la posizione scapolare, senza dolore anteriore"},{"error":"Manubri che si avvicinano in alto perdendo tensione","cause":"Ricerca del picco di contrazione","fix":"Mantieni una distanza costante e fermati prima del contatto"}]'::jsonb,
 null,
 2, false, null, 150),

(null, 'Distensioni su panca inclinata con manubri',
