(null, 'Affondo bulgaro',
 array['bulgarian split squat','affondo bulgaro','split squat bulgaro','squat bulgaro'],
 'quadricipiti', array['glutei','ischiocrurali','adduttori','addome'], 'manubri', 'lunge', 'sagittal', 'multi', true, 'weight_reps',
